arguments.command:
cd /workspace && for inp in '' 'not json' '[]' '{}' '{"jobs":[]}' '{"jobs":[{"gateway":"g","ingress":{"kind":"untrusted"},"trusted_out":true,"raw":5}]}' '{"jobs":[{"gateway":"g","ingress":{"kind":"untrusted"},"trusted_out":true,"source":0}]}' '{"jobs":[{"gateway":"g","ingress":{"kind":"untrusted"},"trusted_out":true,"source":99}]}' '{"jobs":[{"gateway":"g","ingress":{"kind":"bogus"},"trusted_out":true,"raw":"x"}]}'; do
  printf '%s' "$inp" | python3 submission/gateway.py > /tmp/o.json 2>/tmp/e.txt; echo "rc=$? in=<$inp> out=$(cat /tmp/o.json) err=$(head -c 100 /tmp/e.txt)";
done
